<?php
defined('ABSPATH')||exit;
final class POB_Portfolio_Admin {
 public static function boot(){add_action('add_meta_boxes',function(){if(!current_user_can('manage_options'))return;foreach(['freelancer','service'] as $type)add_meta_box('pob-video-portfolio','POBlancer video portfolio',[__CLASS__,'render'],$type,'normal','default');});foreach(['freelancer','service'] as $type)add_action('save_post_'.$type,[__CLASS__,'save'],30,2);add_action('admin_notices',function(){$key='pob_portfolio_admin_'.get_current_user_id();$message=get_transient($key);if($message){delete_transient($key);echo '<div class="notice notice-error"><p>'.esc_html($message).'</p></div>';}});}
 public static function render($post){$rows=(array)get_post_meta($post->ID,POB_Video_Portfolio::META,true);wp_nonce_field('pob_portfolio_admin_'.$post->ID,'pob_portfolio_nonce');echo '<p>Edit the same videos shown in the React freelancer profile or service gallery. Enter YouTube or public Instagram links. Blank rows are ignored. Check Remove to delete a video.</p><input type="hidden" name="pob_portfolio_revision" value="'.esc_attr(hash('sha256',wp_json_encode(array_values($rows)))).'">';
  for($i=0;$i<12;$i++){$r=$rows[$i]??[];echo '<fieldset style="padding:12px 0;border-bottom:1px solid #ddd"><legend>Video '.($i+1).'</legend><p><label>Title <input class="widefat" name="pob_portfolio['.$i.'][title]" maxlength="100" value="'.esc_attr($r['title']??'').'"></label></p><p><label>Video link <input class="widefat" type="url" name="pob_portfolio['.$i.'][url]" value="'.esc_attr($r['url']??'').'" '.(!empty($r['attachment_id'])?'readonly':'').'></label></p><input type="hidden" name="pob_portfolio['.$i.'][attachment_id]" value="'.absint($r['attachment_id']??0).'"><label>Format <select name="pob_portfolio['.$i.'][aspect]"><option value="16:9" '.selected($r['aspect']??'16:9','16:9',false).'>Landscape 16:9</option><option value="9:16" '.selected($r['aspect']??'','9:16',false).'>Portrait 9:16</option></select></label> <label><input type="checkbox" name="pob_portfolio['.$i.'][remove]" value="1"> Remove</label></fieldset>';}
 }
 public static function save($id,$post){
  if(!isset($_POST['pob_portfolio_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['pob_portfolio_nonce'])),'pob_portfolio_admin_'.$id)||!current_user_can('manage_options')||!current_user_can('edit_post',$id)||wp_is_post_revision($id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;
  $rows=[];foreach((array)wp_unslash($_POST['pob_portfolio']??[]) as $row)if(is_array($row)&&empty($row['remove'])&&(!empty($row['url'])||!empty($row['attachment_id'])))$rows[]=$row;
  $clean=POB_Video_Portfolio::normalize($rows,(int)$post->post_author);if(is_wp_error($clean)){set_transient('pob_portfolio_admin_'.get_current_user_id(),$clean->get_error_message(),120);return;}
  global $wpdb;$lock='pob_video_portfolio_'.$id;if((int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,3)',$lock))!==1){set_transient('pob_portfolio_admin_'.get_current_user_id(),'The video portfolio is being edited. Reload and try again.',120);return;}
  try{wp_cache_delete($id,'post_meta');$before=get_post_meta($id,POB_Video_Portfolio::META,true);$before=is_array($before)?array_values($before):[];if(($_POST['pob_portfolio_revision']??'')!==hash('sha256',wp_json_encode($before))){set_transient('pob_portfolio_admin_'.get_current_user_id(),'The video portfolio changed. Reload before saving it.',120);return;}if($before!==$clean)update_post_meta($id,POB_Video_Portfolio::META,$clean);}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}
 }
}
POB_Portfolio_Admin::boot();
